<?php
namespace App\Filament\Admin\Pages;
use App\Models\{FoundationSkDocument,FoundationSkTemplate,School,User};
use App\Services\{FoundationSkDocumentService,FoundationSkMatchingService};
use Filament\Pages\Page; use Filament\Schemas\Components\View; use Filament\Schemas\Schema; use Filament\Notifications\Notification; use Illuminate\Support\Facades\DB; use Livewire\WithFileUploads; use Throwable;
class FoundationSkDashboard extends Page
{
 use WithFileUploads;
 private const MAX_FILE_KB=614400;
 protected static ?string $slug='foundation-sk-dashboard'; protected static ?string $title='Dashboard SK Yayasan'; protected static bool $shouldRegisterNavigation=false;
 public int $tahunSk; public ?int $skTemplateId=null; public ?int $uploadAdminId=null; public ?int $schoolId=null; public array $files=[]; public $uploadFile=null; public array $result=[];
 public static function canAccess():bool{return auth()->user()?->isAdminInduk()||(auth()->user()?->hasRole(User::ROLE_ADMIN_SEKOLAH_MADRASAH)&&auth()->user()->can('sk-yayasan.view'));}
 public function mount():void{$this->tahunSk=(int)now()->year;}
 private function documentQuery(){ $q=FoundationSkDocument::query();$u=auth()->user();if($u?->isAdminInduk())return $q; $schoolIds=$u?->accessibleSchoolIds()??[];return $q->where(function($query)use($schoolIds){$query->whereHas('user.employee',fn($employee)=>$employee->whereIn('school_id',$schoolIds))->orWhereHas('user.memberships',fn($membership)=>$membership->active()->whereIn('school_id',$schoolIds));}); }
 public function content(Schema $schema):Schema{return $schema->components([View::make('filament.admin.pages.foundation-sk-dashboard')->viewData(function(){ $q=$this->documentQuery();$actor=auth()->user();$adminRecipients=User::query()->where('is_active',true)->whereHas('roles',fn($role)=>$role->where('name',User::ROLE_ADMIN_SEKOLAH_MADRASAH))->whereHas('memberships',fn($membership)=>$membership->active()->whereIn('school_id',$actor?->accessibleSchoolIds()??[]))->with('memberships.school')->orderBy('name')->get()->mapWithKeys(fn(User $user)=>[$user->id=>sprintf('%s — %s',$user->name,$user->memberships->first()?->school?->name??'Sekolah belum ditentukan')]);return ['templates'=>FoundationSkTemplate::where('is_active',true)->orderBy('name')->get(),'adminRecipients'=>$adminRecipients,'schools'=>School::query()->accessibleTo(auth()->user())->where('is_active',true)->pluck('name','id'),'totalTemplates'=>FoundationSkTemplate::count(),'totalDocuments'=>(clone $q)->count(),'currentYearDocuments'=>(clone $q)->where('tahun_sk',now()->year)->count(),'connectedUsers'=>(clone $q)->distinct('user_id')->count('user_id'),'documents'=>(clone $q)->with(['user.employee.school','user.memberships.school','template'])->latest()->limit(10)->get()];})]);}
 public function uploadToSchoolAdmin():void{abort_unless(auth()->user()?->isAdminInduk()||auth()->user()?->can('sk-yayasan.manage'),403);$this->validate(['uploadAdminId'=>'required|integer|exists:users,id','tahunSk'=>'required|integer|min:2000|max:2200','skTemplateId'=>'nullable|integer|exists:foundation_sk_templates,id','uploadFile'=>'required|file|mimes:pdf|max:'.self::MAX_FILE_KB]);$actor=auth()->user();$admin=User::with('memberships')->findOrFail($this->uploadAdminId);abort_unless($admin->is_active&&$admin->hasRole(User::ROLE_ADMIN_SEKOLAH_MADRASAH),403);abort_unless($actor->isAdminInduk()||$admin->memberships()->active()->whereIn('school_id',$actor->accessibleSchoolIds())->exists(),403);try{app(FoundationSkDocumentService::class)->store($admin,$this->tahunSk,$this->skTemplateId,$this->uploadFile,$actor,'single');$this->reset('uploadFile','uploadAdminId');Notification::make()->success()->title('SK berhasil dikirim')->body('Dokumen sudah tersedia untuk Admin Madrasah/Sekolah tujuan.')->send();}catch(Throwable $exception){report($exception);Notification::make()->danger()->title('SK belum berhasil dikirim')->body('Penyimpanan dokumen gagal. Periksa log aplikasi dan konfigurasi penyimpanan.')->send();}}
 public function importBatch():void{$this->authorizeImport();$this->validate(['tahunSk'=>'required|integer|min:2000|max:2200','skTemplateId'=>'required|exists:foundation_sk_templates,id','schoolId'=>'nullable|integer','files'=>'required|array|min:1','files.*'=>'file|mimes:pdf|max:'.self::MAX_FILE_KB]);$this->result=['total_files'=>count($this->files),'matched_count'=>0,'updated_count'=>0,'unmatched_files'=>[],'ambiguous_files'=>[],'error_files'=>[]];$matcher=app(FoundationSkMatchingService::class);foreach($this->files as $file){$match=$matcher->match($file,auth()->user(),$this->schoolId);if($match['status']==='unmatched'){$this->result['unmatched_files'][]=$file->getClientOriginalName();continue;}if($match['status']==='ambiguous'){$this->result['ambiguous_files'][]=$file->getClientOriginalName();continue;}try{$before=$this->documentQuery()->where(['user_id'=>$match['employee']->user_id,'tahun_sk'=>$this->tahunSk,'sk_template_id'=>$this->skTemplateId])->exists();DB::transaction(fn()=>app(FoundationSkDocumentService::class)->store($match['employee']->user,$this->tahunSk,$this->skTemplateId,$file,auth()->user(),'batch',$match['matched_by']));$before?$this->result['updated_count']++:$this->result['matched_count']++;}catch(Throwable $exception){report($exception);$this->result['error_files'][]=$file->getClientOriginalName();}}$this->reset('files');Notification::make()->success()->title('Import selesai')->body('File PDF yang valid sudah diproses.')->send();}
 private function authorizeImport():void{abort_unless(static::canAccess()&&auth()->user()->can('sk-yayasan.manage'),403);if($this->schoolId!==null)abort_unless(auth()->user()->isAdminInduk()||auth()->user()->accessibleSchoolIds()->contains($this->schoolId),403);}
}
